/**
 * Runtime contracts for the adaptive-teaching API.
 *
 * This is deliberately separate from TypeScript interfaces: content generated by
 * an LLM and received from the browser is untrusted until these functions accept
 * it.  The flexible `context` object avoids a fixed task catalogue.
 */

export const WORKFLOW_STATES = [
  "gathering_information", "plan_ready_for_review", "blocked", "approved",
  "in_progress", "completed", "cancelled", "needs_caretaker_input",
] as const;
export type WorkflowState = typeof WORKFLOW_STATES[number];

export const OBSERVATION_SOURCES = [
  "camera_observed", "camera_uncertain", "caretaker_reported", "unconfirmed",
] as const;
export type ObservationSource = typeof OBSERVATION_SOURCES[number];

export const BASIC_MR_DOMAINS = [
  "motor",
  "activities_of_daily_living",
  "language",
  "reading_writing",
  "number_time",
  "domestic_social",
  "prevocational_money",
] as const;
export type BasicMrDomain = typeof BASIC_MR_DOMAINS[number];

export const FACP_DOMAINS = ["personal", "social", "academic", "occupational", "recreational"] as const;
export type FacpDomain = typeof FACP_DOMAINS[number];

export const SKILL_ASSESSMENT_STATUSES = [
  "not_assessed", "not_yet_demonstrated", "developing", "demonstrated",
] as const;
export type SkillAssessmentStatus = typeof SKILL_ASSESSMENT_STATUSES[number];

export const LEARNING_OPPORTUNITIES = ["yes", "no", "unknown"] as const;
export type LearningOpportunity = typeof LEARNING_OPPORTUNITIES[number];

export const ASSISTANCE_LEVELS = [
  "independent", "occasional_cue", "gestural_prompting", "verbal_prompting",
  "modelling", "physical_prompting", "fully_dependent", "not_applicable",
  "insufficient_opportunity",
] as const;
export type AssistanceLevel = typeof ASSISTANCE_LEVELS[number];

export const PERFORMANCE_OUTCOMES = [
  "completed_independently", "completed_with_assistance", "partially_completed",
  "not_completed", "not_attempted", "unable_to_determine",
] as const;
export type PerformanceOutcome = typeof PERFORMANCE_OUTCOMES[number];

export type IdSkillAssessmentInput = {
  domain: BasicMrDomain;
  skillName: string;
  assessmentStatus: SkillAssessmentStatus;
  learningOpportunity: LearningOpportunity;
  observerType: "caretaker" | "educator";
  observationDate: string;
  context: string | null;
  example: string | null;
  correctsId: number | null;
};

export type IdFunctionalAssessmentInput = {
  domain: FacpDomain;
  activityName: string;
  assistanceLevel: AssistanceLevel;
  performanceOutcome: PerformanceOutcome;
  observerType: "caretaker" | "educator";
  observationDate: string;
  context: string | null;
  example: string | null;
  correctsId: number | null;
};

export type TeachingStep = {
  id: string;
  title: string;
  instruction: { en: string; hi?: string };
  expectedObservableAction: string;
  camera: {
    observable: boolean;
    supportedObjectLabels?: string[];
    cannotEstablish: string;
  };
  prompting: { strategy: string; waitSeconds: number };
  adaptations?: string[];
  visualCue?: string;
};

export type TeachingPlan = {
  learningGoal: string;
  summary: string;
  prerequisites?: string[];
  relevantContext?: string[];
  steps: TeachingStep[];
  safetyConsiderations: string[];
  progressReviewCriteria: string[];
};

export type InterviewDecision = {
  state: "gathering_information" | "plan_ready_for_review" | "blocked";
  nextQuestion?: string;
  message: string;
  contextUpdates?: Record<string, unknown>;
  blockedReason?: string;
};

type JsonObject = Record<string, unknown>;

function asObject(value: unknown): JsonObject | null {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? value as JsonObject
    : null;
}

function text(value: unknown, max = 1_000): string | null {
  if (typeof value !== "string") return null;
  const normalized = value.trim();
  return normalized.length > 0 && normalized.length <= max ? normalized : null;
}

function optionalField(value: unknown, field: string, errors: string[]): string | null {
  if (value === undefined || value === null || value === "") return null;
  if (typeof value !== "string" || value.trim().length > 2_000) {
    errors.push(`${field} must be at most 2000 characters`);
    return null;
  }
  return value.trim() || null;
}

function validDate(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00.000Z`);
  return Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}

function correctionId(value: unknown, errors: string[]): number | null {
  if (value === undefined || value === null || value === "") return null;
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 1) {
    errors.push("correctsId must be a positive integer");
    return null;
  }
  return value;
}

export function parseIdSkillAssessment(value: unknown): { assessment?: IdSkillAssessmentInput; errors: string[] } {
  const input = asObject(value);
  const errors: string[] = [];
  if (!input) return { errors: ["Assessment must be a JSON object"] };

  const domain = input.domain;
  const skillName = text(input.skillName, 160);
  const assessmentStatus = input.assessmentStatus;
  const learningOpportunity = input.learningOpportunity;
  const observerType = input.observerType;
  const observationDate = input.observationDate;
  if (!BASIC_MR_DOMAINS.includes(domain as BasicMrDomain)) errors.push("domain is invalid");
  if (!skillName) errors.push("skillName must be between 1 and 160 characters");
  if (!SKILL_ASSESSMENT_STATUSES.includes(assessmentStatus as SkillAssessmentStatus)) errors.push("assessmentStatus is invalid");
  if (!LEARNING_OPPORTUNITIES.includes(learningOpportunity as LearningOpportunity)) errors.push("learningOpportunity is invalid");
  if (observerType !== "caretaker" && observerType !== "educator") errors.push("observerType is invalid");
  if (!validDate(observationDate)) errors.push("observationDate must be a valid YYYY-MM-DD date");
  const context = optionalField(input.context, "context", errors);
  const example = optionalField(input.example, "example", errors);
  const correctsId = correctionId(input.correctsId, errors);

  if (errors.length || !skillName || !validDate(observationDate)) return { errors };
  return {
    assessment: {
      domain: domain as BasicMrDomain,
      skillName,
      assessmentStatus: assessmentStatus as SkillAssessmentStatus,
      learningOpportunity: learningOpportunity as LearningOpportunity,
      observerType: observerType as "caretaker" | "educator",
      observationDate,
      context,
      example,
      correctsId,
    },
    errors,
  };
}

export function parseIdFunctionalAssessment(value: unknown): { assessment?: IdFunctionalAssessmentInput; errors: string[] } {
  const input = asObject(value);
  const errors: string[] = [];
  if (!input) return { errors: ["Assessment must be a JSON object"] };

  const domain = input.domain;
  const activityName = text(input.activityName, 160);
  const assistanceLevel = input.assistanceLevel;
  const performanceOutcome = input.performanceOutcome;
  const observerType = input.observerType;
  const observationDate = input.observationDate;
  if (!FACP_DOMAINS.includes(domain as FacpDomain)) errors.push("domain is invalid");
  if (!activityName) errors.push("activityName must be between 1 and 160 characters");
  if (!ASSISTANCE_LEVELS.includes(assistanceLevel as AssistanceLevel)) errors.push("assistanceLevel is invalid");
  if (!PERFORMANCE_OUTCOMES.includes(performanceOutcome as PerformanceOutcome)) errors.push("performanceOutcome is invalid");
  if (observerType !== "caretaker" && observerType !== "educator") errors.push("observerType is invalid");
  if (!validDate(observationDate)) errors.push("observationDate must be a valid YYYY-MM-DD date");
  const context = optionalField(input.context, "context", errors);
  const example = optionalField(input.example, "example", errors);
  const correctsId = correctionId(input.correctsId, errors);

  if (errors.length || !activityName || !validDate(observationDate)) return { errors };
  return {
    assessment: {
      domain: domain as FacpDomain,
      activityName,
      assistanceLevel: assistanceLevel as AssistanceLevel,
      performanceOutcome: performanceOutcome as PerformanceOutcome,
      observerType: observerType as "caretaker" | "educator",
      observationDate,
      context,
      example,
      correctsId,
    },
    errors,
  };
}

function optionalTextList(value: unknown, maxItems = 12): string[] | undefined {
  if (value === undefined || value === null) return undefined;
  if (!Array.isArray(value) || value.length > maxItems) return undefined;
  const items = value.map((item) => text(item, 300));
  return items.every(Boolean) ? items as string[] : undefined;
}

function languageText(value: unknown, field: string, errors: string[]): { en: string; hi?: string } | null {
  const object = asObject(value);
  const en = text(object?.en, 500);
  const hi = object?.hi === undefined ? undefined : text(object.hi, 500);
  if (!en || (object?.hi !== undefined && !hi)) {
    errors.push(`${field} must include a short English instruction`);
    return null;
  }
  return hi ? { en, hi } : { en };
}

/** Parse and validate an LLM plan before it is ever persisted or displayed. */
export function validateTeachingPlan(value: unknown): { plan?: TeachingPlan; errors: string[] } {
  const root = asObject(value);
  const errors: string[] = [];
  if (!root) return { errors: ["Plan must be a JSON object"] };

  const learningGoal = text(root.learningGoal, 500);
  const summary = text(root.summary, 1_500);
  const rawSteps = root.steps;
  if (!learningGoal) errors.push("learningGoal is required");
  if (!summary) errors.push("summary is required");
  if (!Array.isArray(rawSteps) || rawSteps.length < 1 || rawSteps.length > 12) {
    errors.push("steps must contain between 1 and 12 items");
  }

  const steps: TeachingStep[] = [];
  if (Array.isArray(rawSteps)) {
    rawSteps.forEach((raw, index) => {
      const step = asObject(raw);
      const id = text(step?.id, 80);
      const title = text(step?.title, 250);
      const instruction = languageText(step?.instruction, `steps[${index}].instruction`, errors);
      const expectedObservableAction = text(step?.expectedObservableAction, 500);
      const camera = asObject(step?.camera);
      const observable = typeof camera?.observable === "boolean" ? camera.observable : null;
      const cannotEstablish = text(camera?.cannotEstablish, 500);
      const supportedObjectLabels = optionalTextList(camera?.supportedObjectLabels, 15);
      const prompting = asObject(step?.prompting);
      const strategy = text(prompting?.strategy, 500);
      const waitSeconds = typeof prompting?.waitSeconds === "number" && Number.isInteger(prompting.waitSeconds)
        && prompting.waitSeconds >= 2 && prompting.waitSeconds <= 300
        ? prompting.waitSeconds
        : null;
      const adaptations = optionalTextList(step?.adaptations);
      const visualCue = text(step?.visualCue, 500) ?? "Show a simple picture or demonstration of this step.";

      if (!id || !title || !instruction || !expectedObservableAction || observable === null || !cannotEstablish || !strategy || waitSeconds === null) {
        errors.push(`steps[${index}] is missing or has an invalid required field`);
        return;
      }
      steps.push({
        id, title, instruction, expectedObservableAction,
        camera: { observable, supportedObjectLabels, cannotEstablish },
        prompting: { strategy, waitSeconds }, adaptations, visualCue,
      });
    });
  }

  const safetyConsiderations = optionalTextList(root.safetyConsiderations);
  const progressReviewCriteria = optionalTextList(root.progressReviewCriteria);
  if (!safetyConsiderations?.length) errors.push("safetyConsiderations is required");
  if (!progressReviewCriteria?.length) errors.push("progressReviewCriteria is required");
  if (new Set(steps.map((step) => step.id)).size !== steps.length) errors.push("step ids must be unique");

  if (errors.length || !learningGoal || !summary || !safetyConsiderations || !progressReviewCriteria) return { errors };
  return {
    plan: {
      learningGoal, summary, steps, safetyConsiderations, progressReviewCriteria,
      prerequisites: optionalTextList(root.prerequisites),
      relevantContext: optionalTextList(root.relevantContext),
    },
    errors: [],
  };
}

/** Accept only the three pre-approval states returned by the interview model. */
export function validateInterviewDecision(value: unknown): { decision?: InterviewDecision; errors: string[] } {
  const root = asObject(value);
  if (!root) return { errors: ["Interview response must be a JSON object"] };
  const state = root.state;
  const message = text(root.message, 1_000);
  const nextQuestion = root.nextQuestion === undefined ? undefined : text(root.nextQuestion, 1_000) ?? undefined;
  const blockedReason = root.blockedReason === undefined ? undefined : text(root.blockedReason, 1_000) ?? undefined;
  const contextUpdates = root.contextUpdates === undefined ? undefined : asObject(root.contextUpdates);
  if (state !== "gathering_information" && state !== "plan_ready_for_review" && state !== "blocked") {
    return { errors: ["Interview response has an invalid state"] };
  }
  if (!message) return { errors: ["Interview response is missing its message"] };
  if (state === "gathering_information" && !nextQuestion) return { errors: ["A gathering state needs a nextQuestion"] };
  if (state === "blocked" && !blockedReason) return { errors: ["A blocked state needs a blockedReason"] };
  return { decision: { state, message, nextQuestion, blockedReason, contextUpdates: contextUpdates ?? undefined }, errors: [] };
}

export function parseGeneratedJson(raw: string): unknown {
  return JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, ""));
}
